class SummaryRanges {
    private java.util.TreeMap<Integer, int[]> tree;
    public SummaryRanges() { tree = new java.util.TreeMap<>(); }
    public void addNum(int value) {
        if (tree.containsKey(value)) return;
        Integer lo = tree.lowerKey(value), hi = tree.higherKey(value);
        if (lo != null && tree.get(lo)[1] >= value - 1 && hi != null && hi == value + 1) {
            tree.get(lo)[1] = tree.get(hi)[1];
            tree.remove(hi);
        } else if (lo != null && tree.get(lo)[1] >= value - 1) {
            tree.get(lo)[1] = Math.max(tree.get(lo)[1], value);
        } else if (hi != null && hi == value + 1) {
            tree.put(value, new int[]{value, tree.get(hi)[1]});
            tree.remove(hi);
        } else {
            tree.put(value, new int[]{value, value});
        }
    }
    public int[][] getIntervals() {
        return tree.values().toArray(new int[0][]);
    }
}

class SummaryRanges {
    private boolean[] seen;
    private int min;
    private int max;
    public SummaryRanges() {
        seen = new boolean[10002];
        min = Integer.MAX_VALUE;
        max = Integer.MIN_VALUE;
    }
    public void addNum(int value) {
        seen[value] = true;
        if (value < min) min = value;
        if (value > max) max = value;
    }
    public int[][] getIntervals() {
        java.util.List<int[]> intervals = new java.util.ArrayList<>();
        if (min > max) return new int[0][];
        int i = min;
        while (i <= max) {
            if (seen[i]) {
                int start = i;
                while (i <= max && seen[i]) i++;
                intervals.add(new int[]{start, i - 1});
            } else {
                i++;
            }
        }
        return intervals.toArray(new int[0][]);
    }
}
